# totalistic rule on 8-neighborhood count, with toroidal boundaries
from collections import defaultdict
for torus in (False, True):
 sets=defaultdict(set)
 for di,do in zip(dins,douts):
  b=np.array([[int(x) for x in s] for s in di]); z=np.array([[int(x) for x in s] for s in do])
  for r in range(6):
   for c in range(5):
    vals=[]
    for dr in (-1,0,1):
     for dc in (-1,0,1):
      if dr==dc==0:continue
      rr,cc=r+dr,c+dc
      if torus: vals.append(b[rr%6,cc%5])
      elif 0<=rr<6 and 0<=cc<5: vals.append(b[rr,cc])
    sets[sum(vals)].add(int(z[r,c]))
 print(torus,{k:v for k,v in sets.items() if len(v)>1})

